WITH deduped AS (SELECT * FROM suppliers QUALIFY ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating DESC, id) = 1), metrics AS (SELECT *, LAST_VALUE(rating) IGNORE NULLS OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_rating, AVG(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) rating_avg_6 FROM deduped), with_last AS (SELECT s.id, s.city, s.rating, s.last_known_rating, s.rating_avg_6, latest.cost, latest.product_price FROM metrics s JOIN LATERAL (SELECT c.cost, c.price AS product_price FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) latest ON TRUE), base AS (SELECT id, city, rating, rating_avg_6, cost, product_price, ROUND(product_price / rating_avg_6, 2) product_price_per_rating_avg_6, last_known_rating - product_price last_known_rating_minus_product_price FROM with_last WHERE city IS NOT NULL), deduped_suppliers AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating NULLS LAST, id) AS rn FROM base QUALIFY rn = 1), eligible AS (SELECT s.* FROM deduped_suppliers s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND SIZE(x.tags) > 2)), filtered AS (SELECT *, COALESCE(rating_avg_6, 0) rating_avg_6_filled FROM eligible WHERE rating <= 3.0) SELECT city, SUM(cost) FILTER (WHERE city = 'Chiang Mai') AS chiang_mai_total_cost, COUNT(*) AS cnt, COUNT(CASE WHEN city = 'Tokyo' THEN 1 END) AS tokyo_count, COUNT(CASE WHEN city = 'Singapore' THEN 1 END) AS singapore_count, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT_IF(city = 'London') AS london_events FROM filtered GROUP BY city HAVING cnt < 1000 ORDER BY singapore_count DESC NULLS FIRST;
